import XCTest
import SwiftData
@testable import Stello

/// Folder writes (folder engine plan 4b, part 2): FolderWriter must write the same files
/// as the web's src/lib/folder-write.js. The expected files come from
/// test/fixtures/folder-write.json (FolderWriteFixtures, generated by
/// scripts/make-folder-write-fixtures.mjs). Web twin: test/folder-write.test.js.
final class FolderWriterTests: XCTestCase {
    typealias W = FolderWriter

    private var fixtures: W.JSON { W.parse(FolderWriteFixtures.json)! }

    func testItemFilesMatchTheWeb() throws {
        for c in fixtures["items"]?.array ?? [] {
            let name = c["name"]?.string ?? "?"
            let entities = (c["entities"]?.array ?? []).map { e in
                W.Entity(id: e["id"]!.string!, name: e["name"]!.string!, kind: e["kind"]?.string,
                         aliases: (e["aliases"]?.array ?? []).compactMap(\.string), isPlace: e["type"]?.string == "place",
                         path: e["path"]?.string ?? "")
            }
            var paths = Set((c["paths"]?.array ?? []).compactMap { $0.string?.lowercased() })
            var existing: (path: String, copy: W.Copy)?
            if let ex = c["existing"]?.object {
                existing = (ex["path"]!.string!, W.Copy(header: ex["header"]!.object!, body: ex["body"]?.string ?? ""))
            }
            let out = W.itemFile(c["item"]!.object!, entities: entities, paths: &paths, existing: existing)
            let expect = c["expect"]!
            XCTAssertEqual(out.path, expect["path"]?.string, name)
            XCTAssertEqual(out.text, expect["text"]?.string, name)
            XCTAssertEqual(out.entities.map(\.path), (expect["entities"]?.array ?? []).compactMap { $0["path"]?.string }, name)
            XCTAssertEqual(out.entities.map(\.text), (expect["entities"]?.array ?? []).compactMap { $0["text"]?.string }, name)
            XCTAssertEqual(out.media.map(\.file), (expect["media"]?.array ?? []).compactMap { $0["file"]?.string }, name)
            let back = try XCTUnwrap(W.readCopy(expect["text"]!.string!), name)
            XCTAssertEqual(W.copyText(back), expect["text"]?.string, "round trip: \(name)")
        }
    }

    func testMergesMatchTheWeb() {
        func copy(_ j: W.JSON) -> W.Copy { W.Copy(header: j["header"]!.object!, body: j["body"]?.string ?? "", modified: j["mtime"]?.number ?? 0) }
        for c in fixtures["merges"]?.array ?? [] {
            XCTAssertEqual(W.copyText(W.merge(copy(c["a"]!), copy(c["b"]!))), c["expect"]?["text"]?.string, c["name"]?.string ?? "?")
        }
    }

    func testJSONKeepsKeyOrderAndWritesLikeJavaScript() {
        let src = #"{"b":1,"a":[0.9,1.5,true,null],"s":"é \"q\" \n\u0001/"}"#
        XCTAssertEqual(W.parse(src).map(W.stringify), #"{"b":1,"a":[0.9,1.5,true,null],"s":"é \"q\" \n\u0001/"}"#)
        XCTAssertEqual(W.jsNumber(1e-7), "1e-7")
        XCTAssertEqual(W.jsNumber(1200), "1200")
    }

    func testTrashDaysAndExpiry() {
        let now = Date(timeIntervalSince1970: 1_795_867_200) // 2026-11-28 12:00 UTC
        XCTAssertEqual(W.trashPath("items/2026/11/a.md", now: now), ".trash/2026-11-28/items/2026/11/a.md")
        XCTAssertTrue(W.trashExpired("2026-10-28", now: now))
        XCTAssertFalse(W.trashExpired("2026-10-30", now: now))
        XCTAssertFalse(W.trashExpired("notes", now: now))
    }

    func testOnlyUUIDsCountAsLibraryItems() {
        let files: [String: FolderIndexEntry] = [
            "items/a.md": .init(id: "4c9f1824-45ad-4265-98a6-95b71f16338b", modified: 1, size: 1),
            "people/jane.md": .init(id: "person-jane", modified: 1, size: 1),
            "places/berlin.md": .init(id: "place-berlin", modified: 1, size: 1),
        ]
        XCTAssertEqual(FolderSources.countItems(files), 1)
    }

    func testHeaderEntity() {
        let e = FolderScanner.headerEntity("---\nid: \"person-kometa\"\nname: \"Kometa\"\nkind: \"foundry\"\naliases: [\"Kometa Type\"]\n---\n")
        XCTAssertEqual(e, .init(name: "Kometa", kind: "foundry", aliases: ["Kometa Type"]))
    }

    func testMediaFilesResolveFromTheItemsFolder() {
        let copy = W.readCopy("---\nid: \"x\"\nimages:\n  - {\"file\":\"../../../media/k/1.webp\"}\n  - {\"path\":\"/img/a\"}\n---\n")!
        XCTAssertEqual(FolderSources.mediaFiles(of: copy, at: "items/2026/11/k.md"), ["media/k/1.webp"])
    }

    func testMoveToTrashAndClearOut() throws {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FolderFiles.write(Data("a".utf8), to: root.appendingPathComponent("items/2026/11/a.md"))
        try FolderFiles.move(root.appendingPathComponent("items/2026/11/a.md"), to: root.appendingPathComponent(".trash/2026-11-28/items/2026/11/a.md"))
        XCTAssertFalse(FileManager.default.fileExists(atPath: root.appendingPathComponent("items/2026/11/a.md").path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: root.appendingPathComponent(".trash/2026-11-28/items/2026/11/a.md").path))
        try FolderFiles.write(Data("old".utf8), to: root.appendingPathComponent(".trash/2026-01-01/x.md"))
        FolderFiles.clearTrash(root: root, now: Date(timeIntervalSince1970: 1_795_867_200))
        XCTAssertFalse(FileManager.default.fileExists(atPath: root.appendingPathComponent(".trash/2026-01-01").path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: root.appendingPathComponent(".trash/2026-11-28").path))
    }

    /// End to end on a temp folder: a new save, an edit, an outside edit that gets merged, then
    /// delete to .trash. The folder is removed from the list afterwards (its files are temp).
    @MainActor
    func testSaveEditMergeAndTrashInATempFolder() throws {
        let fm = FileManager.default
        let root = fm.temporaryDirectory.appendingPathComponent("stello-folder-test-\(UUID().uuidString)", isDirectory: true)
        try fm.createDirectory(at: root.appendingPathComponent("people"), withIntermediateDirectories: true)
        try "---\nid: \"person-kometa\"\nname: \"Kometa\"\nkind: \"foundry\"\n---\n".write(to: root.appendingPathComponent("people/kometa.md"), atomically: true, encoding: .utf8)
        let sources = FolderSources.shared
        let before = Set(sources.folders.map(\.id))
        guard case .added = sources.add(url: root) else { return XCTFail("add failed") }
        let added = try XCTUnwrap(sources.folders.first { !before.contains($0.id) })
        defer { sources.remove(added.id); try? fm.removeItem(at: root) }
        // add() reads in the background; read synchronously here.
        guard case .success(let files, _) = FolderScanner.scan(root: root, previous: [:]) else { return XCTFail("scan") }
        sources.indexes[added.id] = files
        sources.rebuildLookup()
        XCTAssertTrue(sources.isWritable(added.id))

        let schema = Schema([Item.self, ItemImage.self, Snippet.self, LocalAttachment.self])
        let container = try ModelContainer(for: schema, configurations: [ModelConfiguration(schema: schema, isStoredInMemoryOnly: true, cloudKitDatabase: .none)])
        let context = container.mainContext
        let item = Item(slug: "kometa-fonts", title: "Kometa fonts", sourceURL: "https://kometa.xyz", author: "Kometa Type Foundry",
                        bodyMarkdown: "My note", addedAt: ISO8601DateFormatter().date(from: "2026-11-28T07:00:00Z")!, kind: "typeface")
        context.insert(item)
        try context.save()

        // Only the test folder may take this save.
        let saves = sources.savesFolderID
        sources.setSavesFolder(added.id)
        defer { if let saves { sources.setSavesFolder(saves) } }

        let path = try XCTUnwrap(sources.write(item))
        XCTAssertEqual(path, "items/2026/11/kometa-fonts.md")
        let file = root.appendingPathComponent(path)
        var text = try String(contentsOf: file, encoding: .utf8)
        XCTAssertTrue(text.contains(#""id":"person-kometa","role":"author""#), text)
        XCTAssertTrue(text.hasSuffix("My note\n"), text)
        XCTAssertEqual(sources.locations(for: item.id).first?.folderID, added.id)

        // An edit Stello made: overwritten.
        item.title = "Kometa"
        XCTAssertNotNil(sources.write(item))
        text = try String(contentsOf: file, encoding: .utf8)
        XCTAssertTrue(text.contains(#"title: "Kometa""#), text)

        // An outside edit, then a Stello edit: merged, the outside note kept.
        Thread.sleep(forTimeInterval: 1.1)
        try text.replacingOccurrences(of: "My note", with: "My note\n\nOutside note").write(to: file, atomically: true, encoding: .utf8)
        item.updatedAt = .now.addingTimeInterval(5)
        item.bodyMarkdown = "My note, edited"
        XCTAssertNotNil(sources.write(item))
        text = try String(contentsOf: file, encoding: .utf8)
        XCTAssertTrue(text.contains("My note, edited") && text.contains("Outside note"), text)

        // Delete: the copy goes to .trash/<today>/.
        sources.trash(itemID: item.id)
        XCTAssertFalse(fm.fileExists(atPath: file.path))
        XCTAssertTrue(fm.fileExists(atPath: root.appendingPathComponent(FolderWriter.trashPath(path)).path))
        XCTAssertTrue(sources.locations(for: item.id).isEmpty)
    }
}
